INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Datenschutz dasselbe wie IT-Sicherheit?', 2, '[{"text": "Nein", "correct": true, "because": "Datenschutz schützt Personen, Sicherheit Systeme"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Schwerpunkte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Datenschutz?', 3, '[{"text": "Personenbezogene Daten schützen", "correct": true, "because": "Privatsphäre sichern"}, {"text": "Hardware optimieren", "correct": false, "because": "Kein Hardware-Fokus"}, {"text": "Netzwerkgeschwindigkeit erhöhen", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen gehören zum Datenschutz?', 5, '[{"text": "Verschlüsselung", "correct": true, "because": "Schützt Datenübertragung"}, {"text": "Zugriffskontrolle", "correct": true, "because": "Beschränkt Zugriff"}, {"text": "Grafikdesign", "correct": false, "because": "Kein Datenschutzmittel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenschutz ist gesetzlich geregelt. b) Er ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pflicht in vielen Ländern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Datenschutz?', 4, '[{"text": "Gesetzliche Vorgaben", "correct": false, "because": "Müssen eingehalten werden"}, {"text": "Datenverarbeitung", "correct": false, "because": "Kern des Schutzes"}, {"text": "Bildschirmfarbe", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Datenschutz nur für digitale Daten gilt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch physische Daten betroffen"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt den Datenschutz in der EU?', 3, '[{"text": "DSGVO", "correct": true, "because": "EU-weite Verordnung"}, {"text": "ISO 27001", "correct": false, "because": "Sicherheitsstandard"}, {"text": "HTML5", "correct": false, "because": "Webtechnologie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien gehören zum Datenschutz?', 5, '[{"text": "Transparenz", "correct": true, "because": "Nutzer informieren"}, {"text": "Datenminimierung", "correct": true, "because": "Nur nötige Daten erheben"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Kein Prinzip"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Datenschutz schützt Privatsphäre. b) Er ist nur für Unternehmen relevant. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Einzelpersonen betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Datenschutz?', 4, '[{"text": "Einwilligung", "correct": false, "because": "Rechtliche Grundlage"}, {"text": "Datenschutzrichtlinien", "correct": false, "because": "Regeln definieren"}, {"text": "Küchenzeile", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Datenschutz nur für personenbezogene Daten?', 2, '[{"text": "Ja", "correct": true, "because": "Fokus auf persönliche Daten"}, {"text": "Nein", "correct": false, "because": "Primär personenbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten fallen unter den Datenschutz?', 4, '[{"text": "Name", "correct": true, "because": "Personenbezogen"}, {"text": "E-Mail-Adresse", "correct": true, "because": "Identifizierbar"}, {"text": "Betriebssystem", "correct": false, "because": "Nicht personenbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Datenschutz unnötig ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Gesetzlich und ethisch wichtig"}, {"text": "Ja", "correct": false, "because": "Schutz erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Datenschutz?', 3, '[{"text": "Rechtskonformität", "correct": true, "because": "Gesetze einhalten"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Sorgfalt wichtiger"}, {"text": "Minimale Kosten", "correct": false, "because": "Schutz zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenschutz erfordert Einwilligung. b) Er ist nur für digitale Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch physische Daten betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es beim Datenschutz?', 5, '[{"text": "Technische Umsetzung", "correct": true, "because": "Komplexe Maßnahmen"}, {"text": "Rechtliche Anforderungen", "correct": true, "because": "Gesetzesvielfalt"}, {"text": "Monitorauflösung", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Datenschutz unwichtig?', 3, '[{"text": "Datenverarbeitungsrichtlinien", "correct": false, "because": "Regeln definieren"}, {"text": "Schulungen", "correct": false, "because": "Sensibilisieren Mitarbeiter"}, {"text": "Tastaturtyp", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Datenschutz verletzt werden?', 3, '[{"text": "Ja", "correct": true, "because": "Durch Fehler oder Angriffe"}, {"text": "Nein", "correct": false, "because": "Nicht garantiert sicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Datenschutz nur für Firmen gilt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Privatpersonen betroffen"}, {"text": "Ja", "correct": false, "because": "Allgemeine Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die DSGVO?', 4, '[{"text": "Regelt Datenschutz", "correct": true, "because": "EU-weite Standards"}, {"text": "Erhöht Netzwerkgeschwindigkeit", "correct": false, "because": "Kein Netzwerkeffekt"}, {"text": "Verbessert Grafik", "correct": false, "because": "Irrelevant"}]');
